import {Flash} from '@primer/react'
import {Octicon} from '@primer/react/deprecated'
import {StopIcon} from '@primer/octicons-react'
import type {ErrorContent} from './types'
import styles from './GeneralErrors.module.css'

interface Props {
  errors: ErrorContent[] | undefined
}

export function GeneralErrors({errors}: Props) {
  if (!errors?.length) return null

  return (
    <>
      {errors.map(error => (
        <Flash key={error.heading} className={styles.flash} variant="danger">
          <div className={styles.iconWrapper}>
            <Octicon icon={StopIcon} size={16} className={styles.dangerIcon} />
          </div>
          <div className={styles.contentWrapper}>
            <span className={styles.heading}>{error.heading}</span>
            <span>{error.message}</span>
          </div>
        </Flash>
      ))}
    </>
  )
}
